#include <memory>

struct Texture {
    int id;
};

int slots_returned = 0;

constexpr auto unload = [](Texture* t) {
    std::cout << "unload" << t->id << ' ';
    delete t;
};

struct SlotDeleter {          // remembers which atlas slot to hand back
    int slot;
    void operator()(Texture* t) const {
        slots_returned += slot;
        delete t;
    }
};

using Simple = std::unique_ptr<Texture, decltype(unload)>;
using Pooled = std::unique_ptr<Texture, SlotDeleter>;

int main() {
    std::cout << std::boolalpha
              << (sizeof(Simple) == sizeof(void*)) << ' '
              << (sizeof(Pooled) == sizeof(void*)) << ' ';
    {
        Simple plain{new Texture{1}};
        Pooled pooled{new Texture{2}, SlotDeleter{5}};
    }
    std::cout << slots_returned << '\n';
}

