#include <vector>

struct Event {
    int code;
};

class Listener {
public:
    virtual ~Listener() = default;
    virtual void on_event(const Event& event) = 0;
};

class Sensor {
public:
    // Non-owning registry: whoever created a listener keeps it alive for as
    // long as it stays subscribed. Sensor never ends a listener's lifetime.
    void subscribe(Listener* listener) { listeners_.push_back(listener); }
    void unsubscribe(Listener* listener) { std::erase(listeners_, listener); }

    void publish(const Event& event) const {
        for (Listener* listener : listeners_) {
            listener->on_event(event);
        }
    }

private:
    std::vector<Listener*> listeners_;  // views, not owners
};

class Display final : public Listener {
public:
    explicit Display(Sensor& sensor) : sensor_(sensor) { sensor_.subscribe(this); }

    // Unsubscribing in the destructor is what makes the raw-pointer view safe:
    // the registry can never hold a pointer to a dead Display.
    ~Display() override { sensor_.unsubscribe(this); }

    void on_event(const Event&) override {}

private:
    Sensor& sensor_;
};

void run() {
    Sensor sensor;
    Display display{sensor};  // this scope owns the Display; the sensor observes
    sensor.publish(Event{7});
}

#include <cstddef>
#include <memory>
#include <utility>

struct Stage {
    virtual ~Stage() = default;
    virtual void run(double* scratch, std::size_t count) = 0;
};

struct Resample final : Stage {
    void run(double*, std::size_t) override {}
};

class Pipeline {
public:
    // Each allocation is owned by a member the instant it exists. If the
    // scratch allocation throws, `stage_` is an already-constructed member and
    // its destructor runs during unwinding, so nothing leaks.
    Pipeline(std::unique_ptr<Stage> stage, std::size_t count)
        : stage_(std::move(stage)),
          scratch_(std::make_unique<double[]>(count)),
          count_(count) {}

    void step() { stage_->run(scratch_.get(), count_); }

private:
    std::unique_ptr<Stage> stage_;
    std::unique_ptr<double[]> scratch_;  // array form: deletes with delete[]
    std::size_t count_;
};

Pipeline make_pipeline(std::size_t count) {
    return Pipeline{std::make_unique<Resample>(), count};
}

#include <memory>
#include <type_traits>

struct db;  // opaque C-library type

extern "C" db* db_open(const char* path);
extern "C" void db_free(db* handle);

struct DbCloser {  // stateless: nothing to remember per handle
    void operator()(db* handle) const noexcept {
        if (handle != nullptr) {
            db_free(handle);
        }
    }
};

using Db = std::unique_ptr<db, DbCloser>;

Db open_db(const char* path) { return Db{db_open(path)}; }

struct Pool;
void recycle(Pool& pool, db* handle) noexcept;

struct PooledCloser {  // stateful: must remember where the handle came from
    Pool* pool;
    void operator()(db* handle) const noexcept {
        if (handle != nullptr) {
            recycle(*pool, handle);
        }
    }
};

using PooledDb = std::unique_ptr<db, PooledCloser>;

PooledDb lease_db(Pool& pool, db* handle) {
    return PooledDb{handle, PooledCloser{&pool}};
}

static_assert(sizeof(Db) == sizeof(void*));
static_assert(sizeof(PooledDb) == 2 * sizeof(void*));
static_assert(!std::is_assignable_v<Db&, PooledDb&&>);

#include <cassert>
#include <memory>
#include <string>
#include <utility>

struct Stage {
    explicit Stage(std::string label) : name(std::move(label)) {}

    std::string name;
    std::shared_ptr<Stage> next;    // owns the rest of the chain
    std::weak_ptr<Stage> previous;  // observes upstream; must not own it

    std::string upstream_name() const {
        // A single lock(): the returned owner keeps the upstream stage alive
        // for the whole body, so there is no window between test and use.
        if (auto upstream = previous.lock()) {
            return upstream->name;
        }
        return "<head>";
    }
};

std::shared_ptr<Stage> link(std::string first, std::string second) {
    auto head = std::make_shared<Stage>(std::move(first));
    auto tail = std::make_shared<Stage>(std::move(second));

    head->next = tail;
    tail->previous = head;  // weak: adds no strong owner

    assert(head.use_count() == 1);
    assert(tail.use_count() == 2);  // local handle plus head->next
    return head;
}

void run() {
    auto head = link("parse", "emit");
    assert(head->next->upstream_name() == "parse");
    assert(head->next->next == nullptr);
    assert(head.use_count() == 1);
}
// head dies -> ~Stage("parse") -> drops next -> ~Stage("emit"): chain gone.

#include <memory>
#include <utility>
#include <vector>

struct Result {
    int code = 0;
};

class Queue;

class Job : public std::enable_shared_from_this<Job> {
public:
    // The only way to build a Job, so external shared ownership always exists
    // before any member function can run. A constructor could not call
    // shared_from_this(): no shared_ptr owns the object yet, so it throws
    // std::bad_weak_ptr.
    static std::shared_ptr<Job> create(int id) {
        return std::shared_ptr<Job>(new Job{id});
    }

    void submit(Queue& queue);

    // Aliasing handle: dereferences to the member but owns the whole Job, so
    // a caller can hold the result without knowing what produced it.
    std::shared_ptr<Result> result_handle() {
        return std::shared_ptr<Result>{shared_from_this(), &result_};
    }

private:
    explicit Job(int id) : id_(id) {}

    int id_;
    Result result_;
};

class Queue {
public:
    void push(std::shared_ptr<Job> job) { pending_.push_back(std::move(job)); }

private:
    std::vector<std::shared_ptr<Job>> pending_;
};

void Job::submit(Queue& queue) {
    queue.push(shared_from_this());  // shares the existing control block
}

void enqueue_one(Queue& queue) {
    auto job = Job::create(3);
    job->submit(queue);
    auto result = job->result_handle();
    // `result` alone keeps the Job alive: ownership follows the control block.
}

#include <cstddef>
#include <utility>

class Packet {
public:
    explicit Packet(int length) : length_(length) {}

    void retain() noexcept { ++refs_; }
    void release() noexcept {
        if (--refs_ == 0) {
            delete this;
        }
    }

    int length() const noexcept { return length_; }

protected:
    virtual ~Packet() = default;

private:
    int length_;
    std::size_t refs_ = 0;
};

class PacketRef {
public:
    PacketRef() noexcept = default;

    explicit PacketRef(Packet* packet) noexcept : packet_(packet) {
        if (packet_ != nullptr) {
            packet_->retain();
        }
    }

    PacketRef(const PacketRef& other) noexcept : PacketRef(other.packet_) {}

    PacketRef(PacketRef&& other) noexcept
        : packet_(std::exchange(other.packet_, nullptr)) {}

    // Retain first, release second. Self-assignment and two handles to the
    // same packet are then safe without a special case: the incoming
    // reference is secured before the outgoing one is given up.
    PacketRef& operator=(const PacketRef& other) noexcept {
        if (other.packet_ != nullptr) {
            other.packet_->retain();
        }
        if (packet_ != nullptr) {
            packet_->release();
        }
        packet_ = other.packet_;
        return *this;
    }

    PacketRef& operator=(PacketRef&& other) noexcept {
        if (this != &other) {
            if (packet_ != nullptr) {
                packet_->release();
            }
            packet_ = std::exchange(other.packet_, nullptr);
        }
        return *this;
    }

    ~PacketRef() {
        if (packet_ != nullptr) {
            packet_->release();
        }
    }

    Packet& operator*() const noexcept { return *packet_; }
    Packet* operator->() const noexcept { return packet_; }
    explicit operator bool() const noexcept { return packet_ != nullptr; }

private:
    Packet* packet_ = nullptr;
};

static_assert(sizeof(PacketRef) == sizeof(void*));

#include <memory>
#include <utility>
#include <vector>

struct Scene {
    int visible() const noexcept { return 42; }
};

// Every per-frame helper borrows: no ownership in the signature, so no count
// traffic and nothing to move through memory at the call boundary.
int cull(const Scene& scene) noexcept { return scene.visible(); }
int shade(const Scene& scene) noexcept { return cull(scene) * 2; }

// The one place shared ownership is real: a capture completes on some later
// frame, so neither side controls the lifetime. This sink takes a share by
// value and moves it into place rather than copying it again.
class Capture {
public:
    void enqueue(std::shared_ptr<const Scene> scene) {
        pending_.push_back(std::move(scene));
    }

private:
    std::vector<std::shared_ptr<const Scene>> pending_;
};

class Renderer {
public:
    // Ownership is built once, at setup, not per frame.
    Renderer() : scene_(std::make_shared<Scene>()) {}

    int frame() const noexcept { return shade(*scene_); }  // zero refcount ops

    void snapshot() { capture_.enqueue(scene_); }  // one increment, deliberate

private:
    std::shared_ptr<Scene> scene_;
    Capture capture_;
};

#include <array>
#include <cstddef>
#include <memory>
#include <string>
#include <unordered_map>
#include <utility>

struct DecodedImage {
    explicit DecodedImage(std::string k) : key(std::move(k)) {}
    std::string key;
    std::array<std::byte, 4u << 20> pixels{};  // four megabytes
};

struct Thumbnail {
    int width = 0;
    int height = 0;
};

// Large object whose weak observers routinely outlive every owner, so the
// two-allocation spelling wins: at strong-count zero the four megabytes are
// DEALLOCATED, and only the small control block stays checked out for the
// cache entry. make_shared would keep the whole combined block alive.
std::shared_ptr<DecodedImage> decode(std::string key) {
    return std::shared_ptr<DecodedImage>(new DecodedImage(std::move(key)));
}

// Small, no retention concern: make_shared is the default. One allocation,
// counts next to the object.
std::shared_ptr<Thumbnail> make_thumbnail(int width, int height) {
    return std::make_shared<Thumbnail>(Thumbnail{width, height});
}

class ImageCache {
public:
    std::shared_ptr<DecodedImage> get(const std::string& key) {
        // The entry is an observation. When the last owner drops the image it
        // is DESTROYED immediately -- a weak_ptr never defers a destructor --
        // and the next lookup rebuilds it.
        if (auto live = entries_[key].lock()) {
            return live;
        }
        auto fresh = decode(key);
        entries_[key] = fresh;
        return fresh;
    }

    std::size_t prune() {
        std::size_t removed = 0;
        for (auto it = entries_.begin(); it != entries_.end();) {
            if (it->second.expired()) {
                it = entries_.erase(it);
                ++removed;
            } else {
                ++it;
            }
        }
        return removed;
    }

private:
    std::unordered_map<std::string, std::weak_ptr<DecodedImage>> entries_;
};
